fn bin_search(a: &[i32], k: i32) -> bool {
    let mut lo: usize = 0;
    let mut hi: usize = a.len(); // exclusive

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let v = a[mid];

        if v == k {
            return true;
        } else if v < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    false
}